package co.fcv.citas.session;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="refresh_sessions",uniqueConstraints=@UniqueConstraint(name="uk_refresh_hash",columnNames="token_hash")) public class RefreshSession { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="user_id",nullable=false) private Long userId; @Column(name="token_hash",nullable=false,length=64) private String tokenHash; @Column(nullable=false) private Instant expiresAt; @Column(nullable=false) private boolean revoked=false; protected RefreshSession(){} public RefreshSession(Long u,String h,Instant e){userId=u;tokenHash=h;expiresAt=e;} public Long getId(){return id;} public Long getUserId(){return userId;} public String getTokenHash(){return tokenHash;} public Instant getExpiresAt(){return expiresAt;} public boolean isRevoked(){return revoked;} public void revoke(){revoked=true;} }
